    {"id": "ZUHOEREN:trinken","vorher": "Wir sollten Wasserflaschen im Klassenraum auffüllen können, weil leere Flaschen auch während des Schultags wieder gefüllt werden.","optionen": [{"text": "An der Füllstelle werden leere Flaschen wieder gefüllt.","ok": true,"info": "Die Antwort gibt den genannten Gedanken unverändert wieder.","warum": [{"text": "Die Antwort gibt den genannten Gedanken unverändert wieder.","ok": true},{"text": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel.","ok": false},{"text": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag.","ok": false}]},{"text": "Mit eigenen Flaschen müssen wir keine fremden Becher benutzen.","ok": false,"info": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel."},{"text": "Unsere Trinkflaschen haben verschiedene Größen und Farben.","ok": false,"info": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag."}]},
    {"id": "ZUHOEREN:lesezeit","vorher": "Wir sollten eine kurze stille Lesezeit einführen, weil alle gleichzeitig lesen und niemand dazwischen spricht.","optionen": [{"text": "Wenn alle still lesen, spricht niemand in die Geschichte hinein.","ok": true,"info": "Die Antwort gibt den genannten Gedanken unverändert wieder.","warum": [{"text": "Die Antwort gibt den genannten Gedanken unverändert wieder.","ok": true},{"text": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel.","ok": false},{"text": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag.","ok": false}]},{"text": "In der Lesezeit können wir unsere Lieblingsbücher zeigen.","ok": false,"info": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel."},{"text": "In der Lesezeit liegen viele Bücher auf den Tischen im Raum.","ok": false,"info": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag."}]},
    {"id": "ZUHOEREN:partnerwahl","vorher": "Wir sollten bei kurzen Partneraufgaben gelegentlich auslosen, weil wir auch mit Kindern außerhalb des Freundeskreises üben.","optionen": [{"text": "Durch Lose üben wir auch mit Kindern außerhalb unserer Freunde.","ok": true,"info": "Die Antwort gibt den genannten Gedanken unverändert wieder.","warum": [{"text": "Die Antwort gibt den genannten Gedanken unverändert wieder.","ok": true},{"text": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel.","ok": false},{"text": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag.","ok": false}]},{"text": "Beim Losen können wir unsere eigenen Namenskärtchen nutzen.","ok": false,"info": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel."},{"text": "Bei einer Partneraufgabe arbeiten jeweils zwei Kinder zusammen.","ok": false,"info": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag."}]},
    {"id": "ZUHOEREN:ordnung","vorher": "Wir sollten gemeinsam benutztes Material fest einsortieren, weil jeder den gleichen Platz für Schere und Kleber kennt.","optionen": [{"text": "Ein fester Platz zeigt allen, wo Schere und Kleber liegen.","ok": true,"info": "Die Antwort gibt den genannten Gedanken unverändert wieder.","warum": [{"text": "Die Antwort gibt den genannten Gedanken unverändert wieder.","ok": true},{"text": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel.","ok": false},{"text": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag.","ok": false}]},{"text": "Beim Einsortieren können wir unsere Materialkisten bemalen.","ok": false,"info": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel."},{"text": "Scheren und Kleber gehören gemeinsam zu unserem Bastelmaterial.","ok": false,"info": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag."}]},
    {"id": "ZUHOEREN:spielregeln","vorher": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären, weil wir schon vor dem Spiel wissen, welche Regeln gelten.","optionen": [{"text": "Nach dem Klären wissen beide Teams, welche Regeln gelten.","ok": true,"info": "Die Antwort gibt den genannten Gedanken unverändert wieder.","warum": [{"text": "Die Antwort gibt den genannten Gedanken unverändert wieder.","ok": true},{"text": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel.","ok": false},{"text": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag.","ok": false}]},{"text": "Vor dem Turnier erfahren wir die Namen der Mannschaften.","ok": false,"info": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel."},{"text": "Bei einem Turnier spielen mehrere Mannschaften gegeneinander.","ok": false,"info": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag."}]},
    {"id": "ZUHOEREN:radstaender","vorher": "Wir sollten Fahrräder an festen Plätzen abstellen, weil kein Rad mitten im Weg vor der Eingangstür steht.","optionen": [{"text": "Mit festen Plätzen steht kein Rad vor unserer Eingangstür.","ok": true,"info": "Die Antwort gibt den genannten Gedanken unverändert wieder.","warum": [{"text": "Die Antwort gibt den genannten Gedanken unverändert wieder.","ok": true},{"text": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel.","ok": false},{"text": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag.","ok": false}]},{"text": "Bei festen Plätzen finden wir die Räder unserer Freunde leichter.","ok": false,"info": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel."},{"text": "Die Fahrradständer unserer Schule stehen neben dem Eingang.","ok": false,"info": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag."}]},
    {"id": "ZUHOEREN:tauschregal","vorher": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen, weil andere Kinder noch verwendbare Sachen weiterbenutzen können.","optionen": [{"text": "Im Regal können andere die noch guten Sachen weiterbenutzen.","ok": true,"info": "Die Antwort gibt den genannten Gedanken unverändert wieder.","warum": [{"text": "Die Antwort gibt den genannten Gedanken unverändert wieder.","ok": true},{"text": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel.","ok": false},{"text": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag.","ok": false}]},{"text": "Beim Tauschen entdecken wir verschiedene Farben und Muster.","ok": false,"info": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel."},{"text": "In einem Tauschregal liegen verschiedene Sachen zum Mitnehmen.","ok": false,"info": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag."}]},
    {"id": "ZUHOEREN:lernpause","vorher": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen, weil wir die sitzende Haltung kurz unterbrechen können.","optionen": [{"text": "In Bewegungspausen unterbrechen wir das lange Sitzen.","ok": true,"info": "Die Antwort gibt den genannten Gedanken unverändert wieder.","warum": [{"text": "Die Antwort gibt den genannten Gedanken unverändert wieder.","ok": true},{"text": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel.","ok": false},{"text": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag.","ok": false}]},{"text": "In der Pause können wir unsere gewählten Bewegungen zeigen.","ok": false,"info": "Die Antwort ersetzt den genannten Grund durch ein anderes Ziel."},{"text": "Eine Bewegungspause unterbricht unsere lange Arbeitsphase.","ok": false,"info": "Die Antwort ergänzt einen bisher nicht besprochenen Vorschlag."}]}
