    {"id": "INSELRAT:pausenecke","meinung": "Wir sollten eine ruhige Pausenecke einrichten. Ziel: nach der Pause konzentriert lernen.","beispiel": "Nach zehn ruhigen Minuten konnte Mila wieder ihrer Aufgabe folgen.","einwaende": [{"id": "INSELRAT_E:pausenecke:1","wer": "Grimbart","datei": "zwerg-11-grimbart","einwand": "Für Ballspiele bleibt dann weniger Platz auf dem Hof.","optionen": [{"text": "Wir nutzen den freien Platz neben der Mauer und lassen das Spielfeld frei.","ok": true,"info": "Die Antwort löst das Problem aus dem genannten Einwand.","warum": [{"text": "Die Antwort löst das Problem aus dem genannten Einwand.","ok": true},{"text": "Die Antwort verbessert einen anderen Teil des Vorhabens.","ok": false},{"text": "Die Antwort beschreibt nur die Durchführung des Vorhabens.","ok": false}]},{"text": "Wir vereinbaren, dass die ruhige Ecke allen Kindern offensteht.","ok": false,"info": "Die Antwort verbessert einen anderen Teil des Vorhabens."},{"text": "Wir regeln, welche ruhigen Spiele in der Ecke erlaubt sind.","ok": false,"info": "Die Antwort beschreibt nur die Durchführung des Vorhabens."}]},{"id": "INSELRAT_E:pausenecke:2","wer": "Amara","datei": "zwerg-10-amara","einwand": "Manche Kinder könnten den ruhigen Platz allein für sich beanspruchen.","optionen": [{"text": "Wir vereinbaren, dass die ruhige Ecke allen Kindern offensteht.","ok": true,"info": "Die Antwort löst das Problem aus dem genannten Einwand.","warum": [{"text": "Die Antwort löst das Problem aus dem genannten Einwand.","ok": true},{"text": "Die Antwort verbessert einen anderen Teil des Vorhabens.","ok": false},{"text": "Die Antwort beschreibt nur die Durchführung des Vorhabens.","ok": false}]},{"text": "Wir nutzen den freien Platz neben der Mauer und lassen das Spielfeld frei.","ok": false,"info": "Die Antwort verbessert einen anderen Teil des Vorhabens."},{"text": "Wir erlauben in der Ecke nur Lesen und leise Gespräche.","ok": false,"info": "Die Antwort beschreibt nur die Durchführung des Vorhabens."}]}]},
    {"id": "INSELRAT:hausaufgaben","meinung": "Wir sollten Hausaufgaben am Ende gemeinsam notieren. Ziel: keine Aufgabe beim Aufschreiben übersehen.","beispiel": "Omar bemerkte beim Vergleich die fehlende zweite Matheaufgabe.","einwaende": [{"id": "INSELRAT_E:hausaufgaben:1","wer": "Grimbart","datei": "zwerg-11-grimbart","einwand": "Das gemeinsame Notieren kostet Zeit am Stundenende.","optionen": [{"text": "Wir reservieren die letzten zwei Minuten fürs gemeinsame Notieren.","ok": true,"info": "Die Antwort löst das Problem aus dem genannten Einwand.","warum": [{"text": "Die Antwort löst das Problem aus dem genannten Einwand.","ok": true},{"text": "Die Antwort verbessert einen anderen Teil des Vorhabens.","ok": false},{"text": "Die Antwort beschreibt nur die Durchführung des Vorhabens.","ok": false}]},{"text": "Wir lesen die Aufgaben beim Vergleichen zusätzlich laut vor.","ok": false,"info": "Die Antwort verbessert einen anderen Teil des Vorhabens."},{"text": "Wir schreiben alle Aufgaben in ein Heft statt auf lose Blätter.","ok": false,"info": "Die Antwort beschreibt nur die Durchführung des Vorhabens."}]},{"id": "INSELRAT_E:hausaufgaben:2","wer": "Amara","datei": "zwerg-10-amara","einwand": "Wer die Tafel schlecht sieht, kann seinen Eintrag nicht vergleichen.","optionen": [{"text": "Wir lesen die Aufgaben beim Vergleichen zusätzlich laut vor.","ok": true,"info": "Die Antwort löst das Problem aus dem genannten Einwand.","warum": [{"text": "Die Antwort löst das Problem aus dem genannten Einwand.","ok": true},{"text": "Die Antwort verbessert einen anderen Teil des Vorhabens.","ok": false},{"text": "Die Antwort beschreibt nur die Durchführung des Vorhabens.","ok": false}]},{"text": "Wir reservieren die letzten zwei Minuten fürs gemeinsame Notieren.","ok": false,"info": "Die Antwort verbessert einen anderen Teil des Vorhabens."},{"text": "Wir prüfen beim Aufschreiben auch das Datum im Aufgabenheft.","ok": false,"info": "Die Antwort beschreibt nur die Durchführung des Vorhabens."}]}]},
    {"id": "INSELRAT:schulbeginn","meinung": "Wir sollten eine Woche lang später mit der Schule beginnen. Ziel: prüfen, ob wir morgens wacher lernen.","beispiel": "Nora notierte jeden Morgen, wie wach sie in der ersten Stunde war.","einwaende": [{"id": "INSELRAT_E:schulbeginn:1","wer": "Grimbart","datei": "zwerg-11-grimbart","einwand": "Unser Schulbus fährt nur zu den bisherigen Zeiten.","optionen": [{"text": "Wir klären zuerst, ob der Bus den Versuch mitmachen kann.","ok": true,"info": "Die Antwort löst das Problem aus dem genannten Einwand.","warum": [{"text": "Die Antwort löst das Problem aus dem genannten Einwand.","ok": true},{"text": "Die Antwort verbessert einen anderen Teil des Vorhabens.","ok": false},{"text": "Die Antwort beschreibt nur die Durchführung des Vorhabens.","ok": false}]},{"text": "Wir beziehen die Kurszeiten in den Versuchsplan der Woche ein.","ok": false,"info": "Die Antwort verbessert einen anderen Teil des Vorhabens."},{"text": "Wir beginnen den Unterricht mit einer ruhigen Arbeitsphase.","ok": false,"info": "Die Antwort beschreibt nur die Durchführung des Vorhabens."}]},{"id": "INSELRAT_E:schulbeginn:2","wer": "Amara","datei": "zwerg-10-amara","einwand": "Durch den späteren Beginn enden die Nachmittagskurse ebenfalls später.","optionen": [{"text": "Wir beziehen die Kurszeiten in den Versuchsplan der Woche ein.","ok": true,"info": "Die Antwort löst das Problem aus dem genannten Einwand.","warum": [{"text": "Die Antwort löst das Problem aus dem genannten Einwand.","ok": true},{"text": "Die Antwort verbessert einen anderen Teil des Vorhabens.","ok": false},{"text": "Die Antwort beschreibt nur die Durchführung des Vorhabens.","ok": false}]},{"text": "Wir klären zuerst, ob der Bus den Versuch mitmachen kann.","ok": false,"info": "Die Antwort verbessert einen anderen Teil des Vorhabens."},{"text": "Wir legen in der Versuchswoche eine zusätzliche Lesepause ein.","ok": false,"info": "Die Antwort beschreibt nur die Durchführung des Vorhabens."}]}]}